# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, x):
#         self.val = x
#         self.left = None
#         self.right = None

class Solution:
    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:
        graph = defaultdict(list)

        def dfs(root):
            if not root:
                return

            for child in (root.left, root.right):
                if child:
                    graph[root.val].append(child.val)
                    graph[child.val].append(root.val)

            dfs(root.left)
            dfs(root.right)

        dfs(root)

        queue = deque([target.val])
        seen = set(queue)
        dist = 0
        while queue:
            n = len(queue)
            level = []
            for _ in range(n):
                node = queue.popleft()
                level.append(node)
                for nei in graph[node]:
                    if nei not in seen:
                        queue.append(nei)
                        seen.add(nei)

            if dist == k:
                return level
            dist += 1
        return []
